//! Independent reference values for the crossed Gage R&R.
//!
//! `tests/reference/gage.json` is generated by `tools/gen_gage.py` (two-way
//! ANOVA and the AIAG components); the test never runs Python.

use fp_core::data::{Column, DataFrame};
use fp_core::gage;
use serde_json::Value;

fn reference() -> Value {
    let raw = include_str!("reference/gage.json");
    serde_json::from_str(raw).expect("valid JSON reference")
}

fn numbers(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("number list")
        .iter()
        .map(|value| value.as_f64().expect("number"))
        .collect()
}

fn frame(case: &Value) -> DataFrame {
    let measurement = numbers(&case["measurement"]);
    let part = numbers(&case["part"]);
    let operator: Vec<String> = case["operator"]
        .as_array()
        .expect("operators")
        .iter()
        .map(|value| value.as_str().expect("operator").to_owned())
        .collect();
    DataFrame::new(vec![
        Column::new_f64("measurement", measurement),
        Column::new_f64("part", part),
        Column::new_text("operator", operator),
    ])
    .expect("frame")
}

fn close(actual: f64, expected: f64, tolerance: f64, what: &str) {
    assert!(
        (actual - expected).abs() <= tolerance * (1.0 + expected.abs()),
        "{what}: {actual} vs oracle {expected}"
    );
}

#[test]
fn crossed_gage_rr_matches_the_anova_oracle() {
    let r = reference();
    let tolerance = r["tolerance"].as_f64().expect("tolerance");
    let model = gage::fit(&frame(&r), "measurement", "part", "operator").expect("gage r&r");
    assert_eq!(model.parts, 10);
    assert_eq!(model.operators, 3);
    assert_eq!(model.replicates, 2);
    assert_eq!(model.n, 60);

    let anova = &r["anova"];
    for (actual, key) in [
        (model.ss_part, "ss_part"),
        (model.ss_operator, "ss_operator"),
        (model.ss_interaction, "ss_interaction"),
        (model.ss_error, "ss_error"),
        (model.f_part, "f_part"),
        (model.f_operator, "f_operator"),
        (model.f_interaction, "f_interaction"),
        (model.p_part, "p_part"),
        (model.p_operator, "p_operator"),
        (model.p_interaction, "p_interaction"),
    ] {
        close(
            actual,
            anova[key].as_f64().expect("anova value"),
            tolerance,
            key,
        );
    }
    assert_eq!(model.df_part, anova["df_part"].as_f64().expect("df part"));
    assert_eq!(
        model.df_operator,
        anova["df_operator"].as_f64().expect("df operator")
    );
    assert_eq!(
        model.df_interaction,
        anova["df_interaction"].as_f64().expect("df interaction")
    );
    assert_eq!(
        model.df_error,
        anova["df_error"].as_f64().expect("df error")
    );

    let components = &r["components"];
    for (actual, key) in [
        (model.repeatability, "repeatability_sd"),
        (model.reproducibility, "reproducibility_sd"),
        (model.grr, "grr_sd"),
        (model.part_sd, "part_sd"),
        (model.total_sd, "total_sd"),
        (model.percent_grr, "percent_grr"),
        (model.percent_ev, "percent_ev"),
        (model.percent_av, "percent_av"),
        (model.ndc, "ndc"),
    ] {
        close(
            actual,
            components[key].as_f64().expect("component"),
            tolerance,
            key,
        );
    }
    // The variance components are reported in the same order.
    let sources = ["Repeatability", "Operator", "Part×Operator", "Part"];
    let variances = [
        components["repeatability"].as_f64().expect("repeatability"),
        components["operator"].as_f64().expect("operator"),
        components["interaction"].as_f64().expect("interaction"),
        components["part"].as_f64().expect("part"),
    ];
    for ((component, source), expected) in model.components.iter().zip(sources).zip(variances) {
        assert_eq!(component.source, source);
        close(component.variance, expected, tolerance, source);
    }
}

#[test]
fn a_missing_measurement_breaks_the_balanced_design() {
    // The crossed ANOVA requires the same number of replicates in every
    // part×operator cell; a missing measurement is reported, not silently
    // re-weighted.
    let r = reference();
    let mut df = frame(&r);
    df.set_missing(0, 0).expect("set missing");
    assert!(gage::fit(&df, "measurement", "part", "operator").is_err());
}

#[test]
fn a_constant_measurement_is_rejected() {
    let r = reference();
    let mut df = frame(&r);
    for row in 0..df.n_rows() {
        df.set_cell(0, row, "10").expect("set cell");
    }
    assert!(gage::fit(&df, "measurement", "part", "operator").is_err());
}

#[test]
fn repeated_columns_are_rejected() {
    let r = reference();
    let df = frame(&r);
    assert!(gage::fit(&df, "part", "part", "operator").is_err());
}
